-- 欧洲官方 1.4 服务端数据 + 汉化 (由 tools/convert_official_db_to_sql.py 自动生成，勿手改)
-- name_cn: 汉化名; cn_source: curated(整理译名,待审阅) / alias_csv(来自 item_name_alias.csv) / pending(待汉化,留空)
BEGIN;
DROP TABLE IF EXISTS official_monster;
CREATE TABLE official_monster ("name" VARCHAR(14), "race" INTEGER, "raceimg" INTEGER, "appr" INTEGER, "lvl" INTEGER, "undead" INTEGER, "cooleye" INTEGER, "exp" INTEGER, "hp" INTEGER, "mp" INTEGER, "ac" INTEGER, "mac" INTEGER, "dc" INTEGER, "dcmax" INTEGER, "mc" INTEGER, "sc" INTEGER, "speed" INTEGER, "hit" INTEGER, "walk_spd" INTEGER, "walkstep" INTEGER, "walkwait" INTEGER, "attack_spd" INTEGER, "name_cn" VARCHAR(64) NOT NULL DEFAULT '', "cn_source" VARCHAR(16) NOT NULL DEFAULT 'pending');
DROP TABLE IF EXISTS official_magic;
CREATE TABLE official_magic ("magid" BIGINT, "magname" VARCHAR(12), "effecttype" INTEGER, "effect" INTEGER, "spell" INTEGER, "power" INTEGER, "maxpower" INTEGER, "defspell" INTEGER, "defpower" INTEGER, "defmaxpower" INTEGER, "job" INTEGER, "needl1" INTEGER, "l1train" BIGINT, "needl2" INTEGER, "l2train" BIGINT, "needl3" INTEGER, "l3train" BIGINT, "delay" INTEGER, "descr" VARCHAR(8), "name_cn" VARCHAR(64) NOT NULL DEFAULT '', "cn_source" VARCHAR(16) NOT NULL DEFAULT 'pending');
DROP TABLE IF EXISTS official_stditems;
CREATE TABLE official_stditems ("idx" BIGINT, "name" VARCHAR(14), "stdmode" INTEGER, "shape" INTEGER, "weight" INTEGER, "anicount" INTEGER, "source" INTEGER, "reserved" INTEGER, "looks" BIGINT, "duramax" BIGINT, "ac" INTEGER, "ac2" INTEGER, "mac" INTEGER, "mac2" INTEGER, "dc" INTEGER, "dc2" INTEGER, "mc" INTEGER, "mc2" INTEGER, "sc" INTEGER, "sc2" INTEGER, "need" INTEGER, "needlevel" INTEGER, "price" BIGINT, "stock" BIGINT, "name_cn" VARCHAR(64) NOT NULL DEFAULT '', "cn_source" VARCHAR(16) NOT NULL DEFAULT 'pending');
COMMIT;
